<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Bids · GigHub</title><?php require dirname(__DIR__).'/partials/page-shell.php'; ?><link rel="stylesheet" href="assets/bids.css?v=1"></head>
<body class="gh-shell"><?php require dirname(__DIR__).'/partials/header.php'; ?><main id="main-content" tabindex="-1" class="gh-bids-layout"><p class="gh-bids-eyebrow">FREELANCER WORKSPACE</p><div class="gh-filter-heading"><h1>My Bids</h1><?php $filterRoute = '/freelancer/bids'; require dirname(__DIR__) . '/partials/status-filter.php'; ?></div><p>Track your proposals. Only pending bids on open, unselected jobs can be edited or withdrawn.</p>
<?php if (in_array($notice,['Your bid has been submitted.','Your bid has been saved.','Your bid has been withdrawn.'],true)): ?><p class="gh-bids-notice" role="status"><?= $escape($notice) ?></p><?php endif; ?>

<?php if ($bids===[]): ?><section class="gh-bid-card"><h2><?= ($status ?? '') !== '' ? 'No bids match this status' : ($page===1?'No bids yet':'No bids on this page') ?></h2><p>Find a project that fits your skills and submit a proposal.</p><a class="gh-button gh-button-primary" href="?route=/jobs">Browse Jobs</a></section><?php endif; ?>
<?php foreach ($bids as $row): ?><?php $mutualCancellation=!empty($row['mutual_cancellation']); $cancelled=$mutualCancellation || $row['job_status']==='cancelled' && $row['awarded_bid_id']===null && $row['status']==='pending'; $selected=$row['job_status']==='awarded' && $row['awarded_bid_id']!==null && (int)$row['awarded_bid_id']===(int)$row['id']; ?><article class="gh-bid-card"><p class="gh-bid-status"><?= $cancelled?'Cancelled':($selected?'Selected — awaiting funding':($row['status']==='rejected' || ($row['status']==='pending' && $row['awarded_bid_id']!==null && (int)$row['awarded_bid_id']!==(int)$row['id']) ? 'Not Selected' : $escape(ucfirst($row['status'])))) ?></p><?php if ($cancelled): ?><p><?= $mutualCancellation ? 'This job has been cancelled by mutual agreement between the Client and Freelancer.' : 'This job was cancelled by the client.' ?></p><?php endif; ?><h2><?php if ($row['job_status']==='open'): ?><a href="?route=/jobs/show&amp;id=<?= (int)$row['job_id'] ?>"><?= $escape($row['title']) ?></a><?php else: ?><?= $escape($row['title']) ?><?php endif; ?></h2><dl class="gh-bid-meta"><div><dt>Proposed amount</dt><dd>RM<?= $escape($row['amount']) ?></dd></div><div><dt>Estimated delivery</dt><dd><?= (int)$row['delivery_days'] ?> days</dd></div><div><dt>Job status</dt><dd><?= $escape(ucwords(str_replace('_',' ',$row['job_status']))) ?></dd></div></dl><?php if ($selected): ?><p class="gh-bids-notice">Your bid was selected. Awaiting funding; no payment has been made and work has not started.</p><?php elseif ($row['job_status']==='awarded' && $row['status']==='pending'): ?><p>Another proposal has been selected. Your bid is read-only while funding is pending.</p><?php endif; ?><details><summary>Read your proposal</summary><div class="gh-bid-proposal"><?= $escape($row['cover_letter']) ?></div></details><?php require dirname(__DIR__).'/partials/proposal-document.php'; ?><div class="gh-bid-actions">
<a class="gh-button gh-button-secondary" href="?route=/messages/thread&amp;bid_id=<?= (int)$row['id'] ?>"><span aria-hidden="true" style="margin-right:0.35rem;">💬</span>Message Client</a>
<?php if ($row['status']==='accepted' || ($row['job_status']==='in_progress' && (int)$row['awarded_bid_id']===(int)$row['id'])): ?><a class="gh-button gh-button-secondary" href="?route=/freelancer/jobs/milestones&amp;job_id=<?= (int)$row['job_id'] ?>"><span aria-hidden="true" style="margin-right:0.35rem;">📋</span>View Milestones</a><?php endif; ?>
<?php if ($row['job_status']==='open' && $row['awarded_bid_id']===null && in_array($row['status'],['pending','withdrawn'],true)): ?><a class="gh-button gh-button-secondary" href="?route=/freelancer/bids/edit&amp;id=<?= (int)$row['id'] ?>"><?= $row['status']==='withdrawn'?'Edit and resubmit':'Manage bid' ?></a><?php endif; ?>
</div>
<?php if (!($row['job_status']==='open' && $row['awarded_bid_id']===null && in_array($row['status'],['pending','withdrawn'],true))): ?><p class="gh-bid-readonly-note"><span class="gh-bid-lock-icon" aria-hidden="true">🔒</span> This bid is read-only.</p><?php endif; ?>
</article><?php endforeach; ?>
<?php if ($page>1 || $hasNext): ?><nav class="gh-bid-actions" aria-label="Bid pages"><?php if ($page>1): ?><a href="?route=/freelancer/bids<?= ($status ?? '') !== '' ? '&amp;status=' . $escape(rawurlencode($status)) : '' ?>&amp;page=<?= $page-1 ?>">Previous</a><?php endif; ?><span>Page <?= $page ?></span><?php if ($hasNext): ?><a href="?route=/freelancer/bids<?= ($status ?? '') !== '' ? '&amp;status=' . $escape(rawurlencode($status)) : '' ?>&amp;page=<?= $page+1 ?>">Next</a><?php endif; ?></nav><?php endif; ?>
</main><?php require dirname(__DIR__).'/partials/footer.php'; ?></body></html>
